    // Never null (the graph card uses the same _verdictMeta || _execMeta pair).
    var _sm = _verdictMeta(s) || _execMeta(s);
    var status = _sm.label;
    var color = _sm.color;
    var indent = opts.indent ? '28px' : '12px';
    var fontSize = opts.indent ? '0.85em' : '0.86em';
